#!/usr/bin/env python3
from pathlib import Path
import base64
import hashlib
import io
import shutil
import subprocess
import sys
import tarfile

PAYLOADS = {
    "front": {"sha256": '889e872abd8e3be1aa62137fcf5fddad043208263a500bef1e8ec1b2ea598692', "data": """"""},
    "back": {"sha256": '4e78d3048aec0979d8f8601fda3d5678344cfe4d63dee48e3630f73bf1c6edcc', "data": """"""},
}

root = Path.cwd().resolve()

is_front = (root / "package.json").exists() and (root / "src/main.jsx").exists()
is_back = (root / "pom.xml").exists() and (root / "src/main/java").exists()

if is_front == is_back:
    print("STOP: impossible d'identifier sans ambiguïté le dépôt frontend ou backend.")
    print("Exécute ce script depuis la racine d'un des deux projets.")
    sys.exit(2)

side = "front" if is_front else "back"

SKIP_DIRS = {
    '.git', '.github', 'node_modules', 'target', 'dist', 'coverage', '.astro',
    'playwright-report', 'test-results', '.idea', '.vscode',
}


def is_skipped(path: Path) -> bool:
    try:
        rel = path.relative_to(root)
    except ValueError:
        return True
    return any(part in SKIP_DIRS for part in rel.parts)


def old_markdown_files():
    files = []
    for pattern in ('*.md', '*.mdx'):
        for p in root.rglob(pattern):
            if not p.is_file() or is_skipped(p):
                continue
            rel = p.relative_to(root)
            if rel == Path('README.md'):
                continue
            if rel.parts and rel.parts[0] == 'documentation':
                continue
            files.append(p)
    return sorted(set(files))


def safe_extract(data: bytes):
    with tarfile.open(fileobj=io.BytesIO(data), mode='r:gz') as tar:
        members = tar.getmembers()
        allowed_roots = {'README.md', 'documentation', '.github'}

        for member in members:
            rel = Path(member.name)
            if not rel.parts or rel.parts[0] not in allowed_roots:
                raise RuntimeError(f"entrée payload inattendue: {member.name}")
            target = (root / rel).resolve()
            target.relative_to(root)
            if not (member.isdir() or member.isfile()):
                raise RuntimeError(f"type d'entrée payload non autorisé: {member.name}")

        for member in members:
            target = root / member.name
            if member.isdir():
                target.mkdir(parents=True, exist_ok=True)
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            source = tar.extractfile(member)
            if source is None:
                raise RuntimeError(f"payload illisible: {member.name}")
            target.write_bytes(source.read())


print("=" * 72)
print(f"INSTALLATION DOCUMENTAIRE — {side.upper()}")
print("=" * 72)
print(f"Racine : {root}")
print()

# Remove only the previous documentation surface. Application source/config remains untouched.
for directory in (root / 'docs', root / 'documentation'):
    if directory.exists():
        print(f"REMOVE DIR  {directory.relative_to(root)}")
        shutil.rmtree(directory)

for p in old_markdown_files():
    print(f"REMOVE DOC  {p.relative_to(root)}")
    p.unlink()

if (root / 'README.md').exists():
    print("REPLACE     README.md")

payload = PAYLOADS[side]
data = base64.b64decode(payload['data'].encode('ascii'))
if hashlib.sha256(data).hexdigest() != payload['sha256']:
    print("STOP: payload documentaire corrompu.")
    sys.exit(3)

try:
    safe_extract(data)
except Exception as exc:
    print(f"STOP: extraction refusée: {exc}")
    sys.exit(4)

required = [
    root / 'README.md',
    root / 'documentation/package.json',
    root / 'documentation/astro.config.mjs',
    root / 'documentation/src/content/docs/index.mdx',
    root / 'documentation/public/diagrams/system-atlas.svg',
    root / 'documentation/public/diagrams/deployment-topology.svg',
    root / 'documentation/diagram-sources/system-atlas.dot',
    root / '.github/workflows/documentation.yml',
]
missing = [str(p.relative_to(root)) for p in required if not p.exists()]
if missing:
    print("STOP: installation incomplète: " + ', '.join(missing))
    sys.exit(5)

node = shutil.which('node')
if node:
    print("CHECK       documentation/scripts/check-docs.mjs")
    result = subprocess.run(
        [node, 'scripts/check-docs.mjs'],
        cwd=root / 'documentation',
        check=False,
    )
    if result.returncode != 0:
        print("STOP: le contrat documentaire a échoué après installation.")
        sys.exit(result.returncode)
else:
    print("NOTE: Node absent; le checker documentaire sera exécuté par la CI dédiée.")

page_count = len(list((root / 'documentation/src/content/docs').rglob('*.md'))) \
    + len(list((root / 'documentation/src/content/docs').rglob('*.mdx')))
diagram_count = len(list((root / 'documentation/public/diagrams').glob('*.svg')))

print()
print("✅ Installation terminée")
print(f"   dépôt              : {side}")
print(f"   pages              : {page_count}")
print(f"   diagrammes SVG     : {diagram_count}")
print("   façade racine      : README.md")
print("   site documentaire  : documentation/")
print("   sources graphes    : documentation/diagram-sources/")
print("   CI documentaire    : .github/workflows/documentation.yml")
print("   code applicatif    : inchangé")
print()
print("Démarrer le site documentaire :")
print("  cd documentation")
print("  npm install")
print("  npm run check")
print("  npm run dev")
print()
print("Valider le build :")
print("  npm run build")
print()
print("Retour au dépôt puis contrôle Git :")
print("  cd ..")
print("  git status --short")
